from pathlib import Path
from lesson_authoring import entry as E
OUT=Path('.cache/batch200/drafts/rewrite_st');OUT.mkdir(parents=True,exist_ok=True)
ASSIGN=json.loads(Path('.cache/batch200/rewrite_st.json').read_text())
TH=[['古希腊语 tithenai，词典形 tithemi','放、安置、设定']]
THEME=TH+[['希腊语 thema → 拉丁语 thema → 古法语 teme／tesme','放在面前的内容 → 讨论对象、题目'],['中古英语 teme → theme','主题；音乐主题；界面风格']]
THEMATIC=TH+[['希腊语 thema → thematikos → 英语 thematic','主题、词干 → 与主题或词干有关的']]
THESIS=TH+[['希腊语 thesis → 拉丁语 thesis → 英语 thesis','放置、提出 → 提出的论点；学位论文']]
HYP=TH+[['希腊语 hypo- + thesis → hypothesis','放在下面作基础 → 作为论证基础的设想'],['晚期拉丁语 hypothesis／法语 hypothese → 英语 hypothesis','假定、假说']]
HYPA=TH+[['希腊语 hypothesis → hypothetikos 的拉丁化形容词支线','假说 → 以假说为基础的'],['英语 hypothetical','假设的、假想的']]
SYN=TH+[['希腊语 syn- + tithenai → syntithenai → synthesis','放在一起 → 组合、综合'],['拉丁语 synthesis → 英语 synthesis','把部分组合成整体；合成']]
SYNA=TH+[['希腊语 syntithenai → synthetikos','放在一起 → 与组合有关的'],['近代拉丁语 syntheticus／法语 synthétique → 英语 synthetic','综合的；后来有合成材料、人工的义']]
W=[
E('theme','/θiːm/','主题；主旋律；主题曲；界面风格','把一件事最想谈、反复出现的核心内容，放到台面中央。','希腊 thema 原有放置、提出的事物之意，经拉丁、法语进入英语。现代音乐与软件用法，分别把它用于主旋律和整体外观。',THEME,'小说中的 theme 常是反复探索的观念，如失去与成长；theme tune 是主题曲；dark theme 是深色界面主题。它不只是一个标题，而是贯穿内容或外观的一条线。','the central theme；a recurring theme；a theme tune；a dark theme。','topic 是讨论对象；theme 常是贯穿作品的观念。例如战争是题材，战争怎样改变人可以是主题。',('Trust is a recurring theme in her novels.','信任是她小说中反复出现的主题。'),('I changed the app to a dark theme.','我把应用改成了深色主题。'),sources=['https://www.etymonline.com/word/theme','https://www.oxfordlearnersdictionaries.com/definition/english/theme']),
E('themed','/θiːmd/','有特定主题的','装饰、活动和内容围着同一个想法转，让人一进来就知道这次玩什么。','theme + -ed；既可理解为主题化动词的分词，也可描述具有某主题的状态。',THEME+[['英语 theme → themed','主题 → 围绕某主题安排的']],'a themed party 是有主题的聚会，themed around space 是围绕太空设计。它只说明有统一题材，不保证内容有多深刻。','a themed event；themed around；a themed exhibition。','themed 说成品按主题布置；thematic 更常说分析、关系或材料属于某个主题。',('The museum opened a themed exhibition about rivers.','博物馆开设了一个关于河流的主题展。'),('The room is themed around early space travel.','房间围绕早期太空旅行来布置。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/themed','https://en.wiktionary.org/wiki/themed#English']),
E('thematic','/θɪˈmætɪk/','主题的；按主题组织的；词干主题元音的〔语言学〕','把材料按它们在谈什么来归组，而不是只按日期、地点排队。','接希腊 thematikos，来自 thema；现代可用 theme 与 -atic 的关系帮助记忆，历史上有独立学术来源。',THEMATIC,'thematic analysis 是从资料中辨认、分析主题。语法里的 thematic vowel 是特定形态结构中的主题元音，通常介于词根与词尾间，不能解释成“句子讨论的主题发出的元音”。','thematic analysis；thematic links；a thematic vowel。','thematic organization 按主题排列；chronological organization 按时间排列。语言学专业义要另看结构定义。',('The exhibition uses thematic sections rather than a timeline.','展览采用主题分区，而非时间线。'),('The researcher identified thematic links between the interviews.','研究者辨认出了各次访谈之间的主题联系。'),sources=['https://www.etymonline.com/word/thematic','https://www.oxfordlearnersdictionaries.com/definition/english/thematic']),
E('thematically','/θɪˈmætɪkli/','从主题上；按主题地','问的是这些内容在谈什么、怎样围绕共同观念连起来。','thematic + -ally；对应主题层面的关系或整理方式。',THEMATIC+[['英语 thematic → thematically','主题的 → 从主题上、按主题地']],'thematically related 是主题相关；arrange thematically 是把同主题的材料放在一组。地点相隔很远的作品，也可能在主题上很接近。','thematically linked；arranged thematically；thematically similar。','visually similar 是看起来像；thematically similar 是核心观念相近，画面可以完全不同。',('The essays are arranged thematically.','这些文章按主题编排。'),('The two films are thematically linked by the idea of home.','两部电影通过“家”这一观念在主题上联系起来。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/thematically','https://en.wiktionary.org/wiki/thematically#English']),
E('athematic','/ˌæθɪˈmætɪk/，亦 /ˌeɪθɪˈmætɪk/','无主题的；无主题元音的〔语言学〕','语法中，词根与变化词尾之间，没有那个起连接作用的主题元音。','a-“无” + thematic。普通意义是没有主题；专门语法义是否定 thematic vowel，不是否定一个词有意义。',THEMATIC+[['英语 a- + thematic → athematic','没有主题或没有主题元音的']],'讨论古希腊语等词形时，athematic verbs 可直接将词尾接到相应词根形式上。音乐或文学中则可能说没有固定主题，不能把两种“主题”混为一谈。','an athematic verb；athematic conjugation。','athematic 与 thematic 的语言学区别在特定元音位置，不是“有没有元音字母”。',('The grammar contrasts thematic and athematic verbs.','语法书对比了有主题元音与无主题元音的动词。'),('In this athematic form, the ending attaches directly to the root.','在这个无主题元音形式中，词尾直接接在词根上。'),sources=['https://en.wiktionary.org/wiki/athematic#English','https://www.merriam-webster.com/dictionary/athematic']),
E('monothematic','英 /ˌmɒnəʊθəˈmætɪk/；美 /ˌmɑːnoʊθəˈmætɪk/','单一主题的','整段讨论或作品主要围着一个中心转，没有不断换题。','mono-“一个” + thematic；也可分析为 mono-、theme 与 -atic。',THEMATIC+[['英语 mono- + thematic → monothematic','一个 + 主题的 → 单一主题的']],'a monothematic composition 围绕一个主要音乐主题组织；a monothematic discussion 集中谈一个题目。名字研究中还可指只由一个传统命名成分构成的名字。','a monothematic work；a monothematic discussion。','monothematic 是主题数目少；monotonous 是单调乏味。一个主题也可以变化丰富。',('The composer builds a rich movement from a monothematic design.','作曲家从单一主题的设计中发展出丰富的乐章。'),('The workshop was deliberately monothematic, focusing on urban water use.','研讨会有意只设一个主题，集中讨论城市用水。'),sources=['https://en.wiktionary.org/wiki/monothematic#English','https://www.merriam-webster.com/dictionary/monothematic']),
E('thesis','/ˈθiːsɪs/','论点；命题；学位论文','把一个主张摆出来，再用整套理由告诉读者为什么应该接受它。','希腊 thesis 表放置、提出，经拉丁语借入英语；论点与学术论文义由提出并论证的内容发展。并非英语 theme 加一个词尾。',THESIS,'the central thesis of a book 是全书的核心论点；write a thesis 是写学位论文。不同地区 thesis 与 dissertation 的学位层级习惯不同，不能凭一个词固定判断是硕士还是博士。','a doctoral thesis；a thesis statement；support a thesis。','topic 是题目；thesis 是你围绕题目提出的主张，也可指完整论文。研究“城市交通”还没有自动给出论点。',('Her thesis argues that small parks can strengthen local communities.','她的论文主张，小公园能够增强社区联系。'),('The evidence does not support the book’s central thesis.','这些证据不支持该书的核心论点。'),sources=['https://www.etymonline.com/word/thesis','https://www.oxfordlearnersdictionaries.com/definition/english/thesis']),
E('theses','/ˈθiːsiːz/','thesis 的复数：论文；论点、命题','当论文或主张不止一项，英语保留了这个古典复数形式。','接 thesis 的希腊、拉丁复数体系；英语由 -sis 对应 -ses，末尾读 /siːz/。',THESIS+[['英语 thesis → theses','一篇论文或一个论点 → 多篇、多项']],'three theses 是三篇论文或三个论点。注意它不是 thesis 加普通 /ɪz/，也不是 these“这些”的长写法。','doctoral theses；competing theses；a collection of theses。','theses 首音 /θ/、中间长 /iː/；these 用 /ð/。词义与语法角色都不同。',('The library stores completed doctoral theses online.','图书馆在线保存已完成的博士论文。'),('The debate compared two competing theses about social change.','辩论比较了两种相互竞争的社会变迁论点。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/thesis','https://www.merriam-webster.com/dictionary/thesis']),
E('hypothesis','英 /haɪˈpɒθəsɪs/；美 /haɪˈpɑːθəsɪs/','假说；假设','先垫一个可能的解释在下面，再看推论和证据能否站得住。','希腊 hypo-“在下” + thesis“放置”，形成作为论证基础的 hypothesis，经拉丁及法语进入英语。',HYP,'科学中的 hypothesis 常是可用证据检验的解释；数学、逻辑中也可指推理时暂时接受的条件。它不等于随口猜测，但也还不是仅凭提出就已证实的结论。','test a hypothesis；support a hypothesis；a working hypothesis。','a theory 在科学中可以是有广泛证据支撑的解释框架，不是 hypothesis 随便升级的等级名称。假说需看具体如何检验。',('The researchers designed an experiment to test the hypothesis.','研究者设计了实验来检验这个假说。'),('For now, we will use that explanation as a working hypothesis.','目前我们会把这个解释作为工作假说。'),sources=['https://www.etymonline.com/word/hypothesis','https://www.oxfordlearnersdictionaries.com/definition/english/hypothesis']),
E('hypotheses','英 /haɪˈpɒθəsiːz/；美 /haɪˈpɑːθəsiːz/','hypothesis 的复数：多个假说、假设','面对同一组现象，可以摆出几个候选解释，逐一比较。','hypothesis 的古典复数形式；词尾 -sis 变 -ses，读 /siːz/。',HYP+[['英语 hypothesis → hypotheses','一个假说 → 多个假说']],'alternative hypotheses 是不同的候选假说；competing hypotheses 是相互竞争的解释。多个假说不必同样有力，还要看证据。','test several hypotheses；competing hypotheses；alternative hypotheses。','hypotheses 是复数；hypothesize 是提出假说的动词，末尾读 /saɪz/。',('The team compared three hypotheses against the same data.','团队用同一组数据比较了三个假说。'),('Several hypotheses remain open to further testing.','几个假说仍有待进一步检验。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/hypothesis','https://www.merriam-webster.com/dictionary/hypothesis']),
E('hypothesize','英 /haɪˈpɒθəsaɪz/；美 /haɪˈpɑːθəsaɪz/','提出假说；假定','把一个可能解释说出来，让它成为下一步可以推演、检验的对象。','hypothesis 的词干 + -ize；英式也常拼 hypothesise。',HYP+[['英语 hypothesis + -ize → hypothesize','假说 → 提出假说']],'hypothesize that... 后面接完整设想。严谨写作通常还会说明为什么这样想、如何检验；这个动词本身不表示已经证明。','hypothesize that；hypothesize a link；hypothesize about。','conclude 是得出结论；hypothesize 是提出待检验或待讨论的解释，两者证据状态不同。',('They hypothesize that light affects the timing of flowering.','他们提出假说，认为光照会影响开花时间。'),('The paper hypothesizes a link between the two patterns.','论文提出，这两种模式可能存在联系。'),sources=['https://www.etymonline.com/word/hypothesize','https://www.oxfordlearnersdictionaries.com/definition/english/hypothesize']),
E('hypothetical','英 /ˌhaɪpəˈθetɪkəl/；美 /ˌhaɪpəˈθetɪkəl/','假设的；假想的','先把一个情形临时摆出来，说“如果这样，会怎样”，暂不声称它真的发生。','接希腊 hypothetikos 的拉丁化形容词支线；与 hypothesis 同族，但英语形容词的借入不能简单排在名词后面。',HYPA,'a hypothetical situation 是为讨论而设的情形；a hypothetical explanation 还未确定是真实解释。讨论假想情况也可以很严谨，并不等于内容毫无价值。','a hypothetical case；a hypothetical question；a hypothetical scenario。','hypothetical 表暂时设想；false 表错误。尚未确定的设想，不能仅凭词义判成假的。',('Let us consider a hypothetical town with no private cars.','我们来考虑一座假想的、没有私家车的城镇。'),('The question is hypothetical; no decision has been made.','这个问题是假设性的，尚未作出决定。'),sources=['https://www.etymonline.com/word/hypothetical','https://www.oxfordlearnersdictionaries.com/definition/english/hypothetical']),
E('hypothetically','/ˌhaɪpəˈθetɪkli/','假设地说；从假想情形出发','先约定“只是设想”，再看看这个条件能推到哪里。','hypothetical + -ly，形成说明讨论方式的副词。',HYPA+[['英语 hypothetical + -ly → hypothetically','假设的 → 假设地说']],'Hypothetically, what would happen if...? 常用来展开假想问题。它不保证说话者一定没有现实动机，但字面上把当前讨论框定为假设。','hypothetically speaking；consider something hypothetically。','theoretically 可指按理论或原则上；hypothetically 更明确地从某个设想条件出发。',('Hypothetically, how would the system work without a central server?','假设没有中央服务器，这个系统会怎样运行？'),('We discussed the change hypothetically before seeing the actual proposal.','看到实际提案之前，我们先假设性地讨论了这项变化。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/hypothetically','https://en.wiktionary.org/wiki/hypothetically#English']),
E('synthesis','/ˈsɪnθəsɪs/','综合；合成','零散材料原来各说各话，现在被接成一个有结构的新整体。','希腊 syn-“一起” + tithenai“放”，经 synthesis、拉丁 synthesis 进入英语。英语先有逻辑等学术用法，后扩展到化学、声音与资料整理。',SYN,'a synthesis of research findings 是把研究结果综合起来；chemical synthesis 是通过反应制得物质；sound synthesis 是合成声音。化学合成不一定让每个产物都比所有原料更复杂。','a synthesis of ideas；chemical synthesis；speech synthesis。','summary 可以只概括原文；synthesis 强调把不同来源、部分相互联系起来。analysis 则常把整体分开分析。',('The review offers a synthesis of findings from several studies.','综述综合了几项研究的发现。'),('The laboratory developed a new route for the synthesis of the compound.','实验室开发了合成该化合物的新路线。'),sources=['https://www.etymonline.com/word/synthesis','https://www.oxfordlearnersdictionaries.com/definition/english/synthesis']),
E('syntheses','/ˈsɪnθəsiːz/','synthesis 的复数：多项综合；多种合成','不止一次把材料组合起来，也可能是几套不同的综合成果或合成过程。','synthesis 的古典复数，-sis 改为 -ses，词尾读 /siːz/。',SYN+[['英语 synthesis → syntheses','一项综合、一次合成 → 多项、多次']],'literature syntheses 是多篇或多项文献综合成果；chemical syntheses 是不同合成。它是名词复数，不是 synthesize 的过去式。','research syntheses；chemical syntheses；compare different syntheses。','syntheses 结尾 /siːz/；synthesize 结尾 /saɪz/。前者数成果或过程，后者说合成动作。',('The chapter compares two syntheses of the same historical evidence.','这一章比较了对同一历史证据的两种综合解释。'),('The chemists reported several syntheses of related compounds.','化学家报告了几种相关化合物的合成。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/synthesis','https://www.merriam-webster.com/dictionary/synthesis']),
E('synthesize','/ˈsɪnθəsaɪz/','综合；合成','主动把不同材料接起来，得到一种物质、声音或新的理解。','synthesis 的词干 + -ize；英式也拼 synthesise。',SYN+[['英语 synthesis + -ize → synthesize','综合、合成 → 进行这种操作']],'synthesize information 是综合信息；synthesize a compound 是合成化合物。也能说生物体合成某种分子，所以不必把这个动词一律理解为人工制造。','synthesize information；synthesize a compound；synthesize sound。','combine 泛指放到一起；synthesize 通常强调形成有结构的成果或物质。',('The report synthesizes evidence from interviews and surveys.','报告综合了访谈与调查中的证据。'),('Cells synthesize proteins from amino acids.','细胞用氨基酸合成蛋白质。'),sources=['https://www.etymonline.com/word/synthesize','https://www.oxfordlearnersdictionaries.com/definition/english/synthesize']),
E('synthesized','/ˈsɪnθəsaɪzd/','已合成的；综合得出的；synthesize 的过去式、过去分词','材料已经经过组合，成为现在看到的成果。','synthesize + -ed，末尾 /z/ 后接 /d/；英式也拼 synthesised。',SYN+[['英语 synthesis → synthesize → synthesized','合成 → 已合成、已综合']],'a synthesized voice 是合成语音；newly synthesized molecules 是新合成的分子。判断人工或生物合成，要看主语与上下文。','a synthesized voice；newly synthesized proteins；synthesized evidence。','synthetic 是性质形容词；synthesized 更突出已经完成合成这一动作。两者在材料语境可能重叠。',('The instructions were read aloud in a synthesized voice.','说明由合成语音朗读出来。'),('The team synthesized the findings into a short briefing.','团队把研究发现综合成了一份简短情况说明。'),sources=['https://en.wiktionary.org/wiki/synthesized#English','https://www.merriam-webster.com/dictionary/synthesize']),
E('synthesizer','英 /ˈsɪnθəsaɪzə/；美 /ˈsɪnθəsaɪzər/','合成器；电子合成乐器','不必先录下一件真实乐器，而是用电子或数字方式生成、塑造声音。','synthesize + -er；把合成的动作变成执行该动作的装置或人。日常最常见是电子音乐设备。',SYN+[['英语 synthesize + -er → synthesizer','合成 → 合成声音等的设备']],'a synthesizer 可以生成音色，并控制音高、滤波、包络等。它常带键盘，也可完全由软件或其他控制器操作，不是所有电子键盘都等于合成器。','a digital synthesizer；a software synthesizer；play a synthesizer。','keyboard 是键盘界面或键盘乐器的广称；synthesizer 说声音生成、塑造功能。',('She created the bass sound with a software synthesizer.','她用软件合成器做出了低音音色。'),('The band added a synthesizer to its live setup.','乐队在现场设备中加入了一台合成器。'),sources=['https://www.etymonline.com/word/synthesizer','https://www.oxfordlearnersdictionaries.com/definition/english/synthesizer']),
E('synthetic','/sɪnˈθetɪk/','合成的；人工制成的；综合性的〔语言学等〕','材料义像把所需成分重新搭出来；语言学义则把较多语法信息装进一个词里。','经法语 synthétique 或近代拉丁 syntheticus，接希腊 synthetikos。这个形容词有自己的历史路线，不只是英语 synthesis 加词尾。',SYNA,'synthetic fabric 是合成纤维织物；synthetic compounds 可以与天然来源的同种分子完全相同，也可能是另一种物质。语言学 synthetic language 则常靠词形组合表达语法信息。合成不自动等于有害或劣质。','synthetic fibres；a synthetic material；a synthetic language。','natural 说来源或形成方式；synthetic 说合成途径。判断性能、风险要看具体物质，不能只看这个标签。',('The jacket contains both wool and synthetic fibres.','这件夹克同时含有羊毛和合成纤维。'),('The course compares analytic and synthetic languages.','课程比较分析语与综合语。'),sources=['https://www.etymonline.com/word/synthetic','https://www.oxfordlearnersdictionaries.com/definition/english/synthetic']),
E('synthetically','/sɪnˈθetɪkli/','通过合成；用综合方式','说明东西是怎样做出来或怎样组织起来的，重点在组合、合成的方式。','synthetic + -ally；常修饰 produce、make、generate 等。',SYNA+[['英语 synthetic → synthetically','合成的 → 通过合成方式']],'produced synthetically 是通过合成路线生产。它本身不交代原料来自哪里、分子是否与天然物相同，仍要读后面的具体说明。','synthetically produced；synthetically generated；prepare synthetically。','artificially 强调人工作用，范围更广；synthetically 更具体地说合成过程。',('The flavour compound can be produced synthetically.','这种风味化合物可以通过合成生产。'),('The software generates speech synthetically.','软件通过合成方式生成语音。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/synthetically','https://en.wiktionary.org/wiki/synthetically#English']),
E('biosynthesis','英 /ˌbaɪəʊˈsɪnθəsɪs/；美 /ˌbaɪoʊˈsɪnθəsɪs/','生物合成','细胞像一座有分工的工厂，通过酶催化，把原料一步步转成所需分子。','bio-“生命、生物” + synthesis“合成”，是现代学术组合。',SYN+[['现代英语 bio- + synthesis → biosynthesis','生命过程中的合成']],'protein biosynthesis 是蛋白质生物合成；其他代谢物也有自己的合成通路。研究生物合成可以在实验室进行，词中的 bio- 说过程性质，不是说研究一定发生在野外。','protein biosynthesis；a biosynthesis pathway；biosynthesis of pigments。','photosynthesis 特指利用光能的相关过程；biosynthesis 更广，许多生物合成不直接利用光。',('The diagram outlines the biosynthesis of a plant pigment.','示意图概述了一种植物色素的生物合成。'),('The experiment measured changes in protein biosynthesis.','实验测量了蛋白质生物合成的变化。'),sources=['https://www.merriam-webster.com/dictionary/biosynthesis','https://en.wiktionary.org/wiki/biosynthesis#English']),
E('biosynthetic','英 /ˌbaɪəʊsɪnˈθetɪk/；美 /ˌbaɪoʊsɪnˈθetɪk/','生物合成的','某条路线、某种酶或某个过程，属于生物体制造分子的那套工作。','bio- + synthetic，与 biosynthesis 的名词关系相对应。',SYNA+[['英语 bio- + synthetic → biosynthetic','合成的 → 与生物合成有关的']],'a biosynthetic pathway 是生物合成通路；biosynthetic enzymes 是参与相关合成的酶。它说明生物化学角色，不等于宣传中的“天然、绝对安全”。','a biosynthetic pathway；biosynthetic enzymes；biosynthetic capacity。','biodegradable 是能被生物降解；biosynthetic 是与生物合成有关，一个说分解，一个说生成。',('The researchers identified an enzyme in the biosynthetic pathway.','研究者找出了这条生物合成通路中的一种酶。'),('The mutation changed the cell’s biosynthetic capacity.','突变改变了细胞的生物合成能力。'),sources=['https://www.merriam-webster.com/dictionary/biosynthetic','https://en.wiktionary.org/wiki/biosynthetic#English']),
E('synthetase','/ˈsɪnθəteɪs/，亦 /ˈsɪnθəteɪz/','合成酶〔常指连接酶类〕','让两个分子连接起来，常借助 ATP 等提供的能量来完成这一步。','synthetic 的 synthet- 词干 + 酶名词尾 -ase；不能写成 synthesis 完整词干直接拼接而忽略 t。',SYNA+[['英语 synthet(ic) + -ase → synthetase','合成的 + 酶 → 催化连接合成的酶']],'许多常用酶名仍含 synthetase，例如 aminoacyl-tRNA synthetase。IUBMB 建议此名限于 ligase 类；synthase 的范围更广，不能用“synthase 一律不用 ATP”来机械区分。','aminoacyl-tRNA synthetase；synthetase activity。','synthetase 指酶；synthesizer 指合成装置。生化名称的具体反应，应查酶分类和反应式。',('The assay measured synthetase activity in the sample.','测定检测了样本中的合成酶活性。'),('The lecture explains how an aminoacyl-tRNA synthetase recognizes its substrates.','讲座解释了氨酰 tRNA 合成酶如何识别其底物。'),sources=['https://www.merriam-webster.com/dictionary/synthetase','https://iubmb.qmul.ac.uk/enzyme/rules.html']),
E('polysynthetic','英 /ˌpɒlisɪnˈθetɪk/；美 /ˌpɑːlisɪnˈθetɪk/','多式综合的〔语言学〕；聚片双晶的〔晶体学〕','语言学里，一个词像装得很满的小句子，里面可以接入许多语法和词汇成分。','poly-“多” + synthetic；语言分类与晶体描述各使用合成、多重组合的意义。',SYNA+[['英语 poly- + synthetic → polysynthetic','多重组合的 → 多式综合的；另用于重复双晶结构']],'polysynthetic language 通常有复杂的词内部结构，一个词可能表达其他语言要用多个词表达的内容。不是“随便哪个词很长”就够；晶体学中还可指重复的薄层双晶结构。','a polysynthetic language；polysynthetic morphology；polysynthetic twinning。','agglutinative 常强调词素边界清楚、逐个连接；polysynthetic 强调高程度的综合构词，两种分类关注点不同。',('The course examines verb structure in a polysynthetic language.','课程考察一种多式综合语言的动词结构。'),('The mineral section shows polysynthetic twinning.','矿物薄片显示出聚片双晶结构。'),sources=['https://www.merriam-webster.com/dictionary/polysynthetic','https://en.wiktionary.org/wiki/polysynthetic#English']),
E('oligosynthetic','英 /ˌɒlɪɡəʊsɪnˈθetɪk/；美 /ˌɑːlɪɡoʊsɪnˈθetɪk/〔按构词标读〕','寡综合的〔少见语言分类术语〕','设想只有少量基本词素，靠反复组合这些“小积木”表达许多意思。','oligo-“少” + synthetic；少的是基本构词成分的数量，不是句子只能表达很少内容。',SYNA+[['英语 oligo- + synthetic → oligosynthetic','少量基本成分 + 组合 → 寡综合的']],'这是较少使用、带理论色彩的分类名称。阅读时应看作者如何定义“少量”及其证据，不能凭某语言常用词根不多就直接贴标签。','an oligosynthetic system；an oligosynthetic model。','polysynthetic 关注单词里能组合很多成分；oligosynthetic 关注可用的基本词素库存少，衡量对象不同。',('The author proposes an oligosynthetic model with a small set of roots.','作者提出了一种只使用少量词根的寡综合模型。'),('The chapter questions whether the language is truly oligosynthetic.','这一章质疑该语言是否真的属于寡综合类型。'),sources=['https://en.wiktionary.org/wiki/oligosynthetic#English']),
]
TREAS=[['希腊语 thesauros','宝库、储藏物；更早来源有争议'],['拉丁语 thesaurus → 通俗拉丁语 *tresaurus','储藏的财物'],['古法语 tresor → 中古英语 tresour','珍宝、财富'],['英语 treasure','珍宝；珍视']]
DOOM=[['原始日耳曼语 *domaz','判断、法规；与更远“放置”根的联系并非定论'],['古英语 dōm → 中古英语 doom','判决、裁断'],['英语 doom','走向厄运的命运；使注定失败']]
APO=TH+[['希腊语 thēkē → apothēkē','放东西的容器 → 存放物品的地方'],['拉丁语 apotheca','储藏室、仓库']]
W += [
E('treasure','英 /ˈtreʒə/；美 /ˈtreʒər/','珍宝；宝贵的人或事物；珍视','值得好好保存的东西：可以是一箱金币，也可以是一封旧信。','经法语传入，现代不拆成 trea + sure。希腊 thesauros 与“放置”的联系有传统解释，也有前希腊借词说，不能写成已确定同源。',TREAS,'不可数 treasure 可以泛指金银财宝；a treasure 是一件珍品，也能亲切地称一个很可贵的人。动词 treasure 把“当作宝贝保存”转成“珍视”，并不要求东西昂贵。','buried treasure；a national treasure；treasure a memory。','value 强调看重价值；treasure 常多一层感情：不舍得失去，愿意留在心里。',('The divers found a chest of treasure near the wreck.','潜水员在沉船附近发现了一箱珍宝。'),('I treasure the letters my grandmother wrote to me.','我很珍惜祖母写给我的信。'),sources=['https://www.etymonline.com/word/treasure','https://www.etymonline.com/word/thesaurus']),
E('treasured','英 /ˈtreʒəd/；美 /ˈtreʒərd/','珍爱的；倍加珍惜的','东西在主人心里有分量，哪怕旁人觉得它很普通。','treasure + -ed；由动词的过去分词作形容词。',TREAS+[['英语 treasure → treasured','珍视 → 被珍爱的']],'a treasured possession 可以是旧玩具、照片或家传物品；treasured memories 是舍不得忘掉的回忆。它说的是感情关系，不是市场价格。','a treasured possession；a treasured friend；treasured memories。','valuable 可能强调值钱；treasured 强调有人珍惜它。',('The faded photograph is one of her most treasured possessions.','这张褪色的照片是她最珍爱的物品之一。'),('We returned to the village with many treasured memories.','我们带着许多珍贵的回忆回到了村子。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/treasured','https://www.merriam-webster.com/dictionary/treasured']),
E('treasury','英 /ˈtreʒəri/；美 /ˈtreʒəri/','金库；国库；财政部门；精选集','最初是把财宝收起来的地方，后来也指管理这笔钱的机构。','英语经古法语 tresorie 借入，承接 tresor“财宝”；不要把历史简化为英语 treasure 临时加 -y。',TREAS[:1]+[['拉丁语 thesaurus → 古法语 tresor / tresorie','财宝 → 保管财宝的地方'],['中古英语 tresorie → 英语 treasury','金库、国库；财政机构']],'the Treasury 常是特定国家财政部门的名称；a treasury of poems 则把好诗比作集中保存的珍宝。美国金融语境的 Treasuries 指国债，需靠上下文分清机构和证券。','the national treasury；Treasury officials；a treasury of stories。','treasure 是珍宝或珍视；treasury 是储藏、管理这些财富的地方或机构。',('The palace treasury contained coins from several centuries.','王宫金库里藏有跨越几个世纪的钱币。'),('The book is a treasury of local stories.','这本书是一部地方故事精选集。'),sources=['https://www.etymonline.com/word/treasury','https://www.oxfordlearnersdictionaries.com/definition/english/treasury']),
E('treasurer','英 /ˈtreʒərə/；美 /ˈtreʒərər/','财务主管；司库','负责把组织的钱收清楚、花明白、记在账上的人。','来自古法语 tresorier、盎格鲁法语 tresorer 等形式，远接 tresor“财宝”；不是 treasury 去尾再加 -er 的历史。',TREAS[:1]+[['拉丁语 thesaurus → 古法语 tresor','财宝'],['古法语 tresorier / 盎格鲁法语 tresorer','掌管财物的人'],['中古英语 tresourer → 英语 treasurer','司库、财务主管']],'学校社团、慈善组织和公司都可能有 treasurer。具体权限因机构而异，核心是负责财务，不是“找宝藏的人”。','club treasurer；elect a treasurer；the treasurer’s report。','accountant 侧重会计工作；treasurer 通常是组织内负责财务管理的职务。',('The club treasurer keeps a record of every donation.','社团财务负责人记录每一笔捐款。'),('She was elected treasurer at the annual meeting.','她在年会上当选为司库。'),sources=['https://www.etymonline.com/word/treasurer','https://www.oxfordlearnersdictionaries.com/definition/english/treasurer']),
E('thesaurus','英 /θɪˈsɔːrəs/；美 /θɪˈsɔːrəs/','同义词词典；分类词汇集','写作时脑中只有一个词，打开这座“词语宝库”，找到意思接近但语气不同的选择。','直接借自拉丁 thesaurus，源于希腊 thesauros“宝库”。与 tithenai 的远源联系有争议，不能据拼写说它一定是“放置”派生。',[['希腊语 thesauros → 拉丁语 thesaurus','宝库；更早来源有不同解释'],['英语 thesaurus','知识或词汇的汇集 → 同义词、分类词汇工具书']],'它提供相关词，不保证词词都能互换。比如 slim 和 skinny 都涉及瘦，褒贬却不同；从 thesaurus 选词后，还得看搭配与语境。','consult a thesaurus；an online thesaurus；a thesaurus entry。','dictionary 主要解释一个词；thesaurus 帮你沿意义找到其他词。',('I used a thesaurus to find a more precise verb.','我查了同义词词典，想找一个更准确的动词。'),('Not every word in a thesaurus entry fits the same sentence.','同义词条目里的词并不是每一个都适合放进同一句话。'),sources=['https://www.etymonline.com/word/thesaurus','https://www.oxfordlearnersdictionaries.com/definition/english/thesaurus']),
E('doom','/duːm/','毁灭；厄运；使注定失败','像坏结局已经等在前面，事情再往下走就会撞上它。','古英语 dōm 本来指判断、判决；英语自己继承了它，并非从希腊语借来。远源或与“放置、设定”有关。',DOOM,'名词 doom 常带强烈的不祥感；动词 doom 常说某个条件使计划、关系等难逃失败。doom a plan to failure 不是正式宣判，而是形象地说失败几乎被决定了。','a sense of doom；spell doom for；doom something to failure。','fate 可以好也可以坏；doom 在现代常指坏结局。',('A sense of doom hung over the abandoned station.','那座废弃车站弥漫着不祥的感觉。'),('The lack of funding doomed the project to failure.','资金不足使这个项目注定失败。'),sources=['https://www.etymonline.com/word/doom','https://www.oxfordlearnersdictionaries.com/definition/english/doom_1']),
E('deem','/diːm/','认为；认定〔正式〕','经过判断，把某人或某物归为“合适、必要、安全”等一类。','从古英语 dēman 继承，远接日耳曼语“判断”名词的派生动词。它与 doom 是亲属词，不是现代英语把 oo 改成 ee。',[['日耳曼语 *domaz → *domjanan','判断 → 作出判断'],['古英语 dēman → 中古英语 demen','判断、裁定'],['英语 deem','认为、认定']],'常见被动 be deemed suitable / necessary，也可以 deem something a success。它比 think 正式，常见于评审、规章或书面评价。','deem it necessary；be deemed unsuitable；deem a proposal acceptable。','seem 是看起来如何；deem 是有人作出如何评价的判断。',('The committee deemed the proposal too expensive.','委员会认为这项提案费用过高。'),('Applications received after Friday will be deemed late.','周五之后收到的申请将被认定为逾期。'),sources=['https://www.etymonline.com/word/deem','https://www.oxfordlearnersdictionaries.com/definition/english/deem']),
E('doomed','/duːmd/','注定失败的；劫数难逃的','还没有结束，却已看得出很难有好结果。','doom + -ed；过去分词转为形容词，结尾读 /md/。',DOOM+[['英语 doom → doomed','使走向坏结局 → 注定失败的']],'be doomed to fail 是注定失败；be doomed from the start 是从一开始就没什么成功希望。日常也会夸张使用，不一定真在说死亡或毁灭。','a doomed attempt；be doomed to failure；doomed from the start。','hopeless 强调看不到希望；doomed 更像坏结局已被决定。',('Without a reliable water supply, the settlement was doomed.','没有可靠的水源，这个定居点注定维持不下去。'),('Their attempt to hide the mistake was doomed from the start.','他们掩盖错误的尝试从一开始就注定失败。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/doomed','https://www.merriam-webster.com/dictionary/doomed']),
E('doomsday','/ˈduːmzdeɪ/','世界末日；最后审判日','原来是神最终作出裁断的日子，后来泛指一切走向灾难的时刻。','古英语 dōmesdæg：dōm“审判”的属格 dōmes + dæg“日”。中间 s 原是所属关系，不是简单复数。',[['古英语 dōm 的属格 dōmes + dæg','审判 → 审判之日'],['古英语 dōmesdæg → 英语 doomsday','最后审判日 → 末日、灾难结局']],'a doomsday scenario 是灾难性的最坏情境；until doomsday 是夸张的“等到天荒地老”。很多现代用法与具体宗教信仰无关。','a doomsday prediction；a doomsday scenario；wait until doomsday。','Doomsday 可专指宗教最后审判；普通 doom 更广，指厄运或毁灭。',('The film opens with a doomsday warning on the radio.','电影开场时，收音机里播着末日警告。'),('We could argue about the details until doomsday.','我们可以一直争这些细节，争到天荒地老。'),sources=['https://www.etymonline.com/word/doomsday','https://www.oxfordlearnersdictionaries.com/definition/english/doomsday']),
E('doomer','英 /ˈduːmə/；美 /ˈduːmər/','悲观地预期灾难或社会崩溃的人〔网络口语〕','谈到未来，总先看到“要完了”的那一面的人。','doom + -er，把厄运观念变成持这种看法的人；现代网络语境扩大了用途。',DOOM+[['英语 doom + -er → doomer','厄运 → 经常预期坏结局的人']],'它可以是自嘲身份，也可以是别人贴的讥讽标签。climate doomer 常指认为气候前景无可挽回的人；AI doomer 的使用也带争论色彩。这个词本身不是心理诊断。','a climate doomer；call someone a doomer；a self-described doomer。','pessimist 泛指悲观者；doomer 往往把悲观推到整体未来、灾难或崩溃。',('He calls himself a doomer, but he still volunteers in his community.','他自称是个对未来极度悲观的人，但仍在社区做志愿服务。'),('The article dismisses every critic as a doomer.','这篇文章把所有批评者都轻率地归为灾难悲观派。'),sources=['https://en.wiktionary.org/wiki/doomer#English','https://dictionary.cambridge.org/dictionary/english/doomer']),
E('doomscroll','英 /ˈduːmskrəʊl/；美 /ˈduːmskroʊl/','不停刷负面新闻','手指一直往下划，眼前接连是坏消息，明知越看越沉重却还在继续。','doom + scroll；也常解释为从 doomscrolling 去掉 -ing 得到的动词。现代构词透明，具体最早先后不强定。',DOOM+[['英语 doom + scrolling → doomscrolling；对应动词 doomscroll','坏消息 + 刷屏 → 不停刷负面新闻']],'通常不及物，说 doomscroll through the news/feed。漫无目的刷搞笑视频一般只是 scroll；这个词的中心是持续吸收负面消息。','doomscroll before bed；doomscroll through the news；stop doomscrolling。','scroll 只是移动页面；doomscroll 同时说刷到的内容与沉迷其中的行为。',('I meant to check one headline, but I doomscrolled for an hour.','我本来只想看一条标题，结果刷坏消息刷了一个小时。'),('She puts her phone away so she will not doomscroll before bed.','她把手机收起来，免得睡前不停刷负面新闻。'),sources=['https://en.wiktionary.org/wiki/doomscroll#English','https://dictionary.cambridge.org/dictionary/english/doomscrolling']),
E('doomscrolling','英 /ˈduːmskrəʊlɪŋ/；美 /ˈduːmskroʊlɪŋ/','不停刷负面新闻的行为','坏消息一条接一条，注意力被拉住，停不下来。','doom + scrolling；也可与动词 doomscroll + -ing 对照。这里只说明现代构词，不把词形较短等同于历史较早。',DOOM+[['英语 doom + scrolling → doomscrolling','不祥的新闻内容 + 连续刷屏']],'名词常不可数：hours of doomscrolling、endless doomscrolling。重点是重复刷负面内容，不是读到一条坏消息就算这种行为。','endless doomscrolling；late-night doomscrolling；spend hours doomscrolling。','news reading 可以是有目的地了解信息；doomscrolling 描写反复往下刷、被负面内容牵着走的状态。',('Late-night doomscrolling left me tired the next morning.','深夜不停刷坏消息让我第二天早上很疲惫。'),('The discussion turned from social media to doomscrolling.','讨论从社交媒体转到了不停刷负面新闻这种行为。'),sources=['https://dictionary.cambridge.org/dictionary/english/doomscrolling','https://en.wiktionary.org/wiki/doomscrolling#English']),
E('boutique','/buːˈtiːk/','精品店；小规模、专门化的〔机构或服务〕','不是铺得很大的百货卖场，而是集中做某一类商品或服务的小店、小机构。','由法语 boutique 借入，经古普罗旺斯语 botica、拉丁 apotheca，远接希腊 apothēkē“储藏处”。',APO+[['古普罗旺斯语 botica → 法语 boutique','储藏、售货的场所 → 小店'],['英语 boutique','精品店；专门提供某类服务的小机构']],'a fashion boutique 通常是服装精品店；a boutique hotel 或 boutique consultancy 强调规模较小、风格或服务专门。这个标签本身不能保证品质。','a fashion boutique；a boutique hotel；a boutique consultancy。','shop 泛指商店；boutique 常突出小而专。它和 bodega 远源相同，现代场景不同。',('She bought the scarf at a small boutique near the station.','她在车站附近的一家小精品店买了那条围巾。'),('The firm is a boutique consultancy specializing in museum projects.','这是一家专做博物馆项目的小型咨询公司。'),sources=['https://www.etymonline.com/word/boutique','https://www.oxfordlearnersdictionaries.com/definition/english/boutique']),
E('bodega','英 /bəʊˈdeɪɡə/；美 /boʊˈdeɪɡə/','酒窖；葡萄酒商店；街角小杂货店〔尤指纽约〕','在西班牙语场景里常想到存酒、卖酒；在纽约街头，则常是买咖啡、三明治和日用品的小店。','借自西班牙语 bodega，远接拉丁 apotheca、希腊 apothēkē。与 boutique 是走了不同语言路线的亲属词。',APO+[['西班牙语 bodega → 英语 bodega','酒窖、酒铺 → 部分美国城市的街区杂货店']],'看地名能帮助判断意思。a Spanish bodega 可能在谈酒业；the bodega on the corner 在纽约语境通常是邻里小店，不需要只卖西班牙商品。','a neighbourhood bodega；the corner bodega；visit a bodega。','boutique 常强调精选、专门商品；bodega 的纽约义更接近日常便利店。',('We stopped at a bodega for coffee and a sandwich.','我们在街角小店停下来买了咖啡和三明治。'),('The guide took us into the old bodega where the wine was stored.','向导带我们走进了存酒的老酒窖。'),sources=['https://www.etymonline.com/word/bodega','https://www.oxfordlearnersdictionaries.com/definition/english/bodega']),
]
ANTI=TH+[['希腊语 antitithenai → antithesis','放在对面 → 对立、对照'],['晚期拉丁语 antithesis → 英语 antithesis','反面；修辞上的对照']]
ANTIA=TH+[['希腊语 antithetos → antithetikos','对放的 → 构成对照的'],['英语 antithetical / antithetic 分别采用希腊形容词材料','相对立的；长形式在英语中并不较晚']]
PAREN=TH+[['希腊语 parentithenai → parenthesis','放在旁边、插入 → 插入的话'],['中世纪拉丁语 parenthesis / 法语 parenthèse → 英语 parenthesis','插入语 → 标示插入语的圆括号']]
PARENA=TH+[['希腊语 parenthetos → 中世纪拉丁语 parentheticus','插入的'],['英语 parenthetical；parenthetic 有借入或缩短解释','插入式的、附带的']]
W += [
E('antithesis','/ænˈtɪθəsɪs/','正相反的事物；对照、对偶','把两件方向相反的事摆在一起，让差别立刻显出来。','anti- 在这里是“对面、相反” + thesis“放置”；完整名词经拉丁语借入。',ANTI,'the antithesis of kindness 是与善良完全相反的东西。修辞上则把相反观念并排，如“承诺的是自由，得到的是束缚”。复数 antitheses，不是 antithesises。','the antithesis of；a striking antithesis；use antithesis。','contrast 可以只是不同；antithesis 通常突出正反对立。',('His cold reply was the antithesis of the welcome we expected.','他冷淡的回应与我们期待的欢迎完全相反。'),('The speech uses antithesis to contrast private wealth with public poverty.','这篇演说用对照手法，把个人财富与公共领域的贫困并列起来。'),sources=['https://www.etymonline.com/word/antithesis','https://www.oxfordlearnersdictionaries.com/definition/english/antithesis']),
E('antithetic','/ˌæntɪˈθetɪk/','对立的；构成对照的〔较少用〕','两边的意思或方向相反，并排看更鲜明。','承接希腊 antithetikos，可与 anti-、thet-“放置”相联系；不能仅凭短就说它早于 antithetical。',ANTIA,'常见于较正式的文学、哲学等材料。可以形容一对观念、人物或意象正好朝相反方向展开；它关心的是对照关系，不是简单的两件东西并列。','antithetic ideas；antithetic pairs；antithetic images。','antithetical 日常书面语更常用；antithetic 在某些技术搭配里固定保留。',('The critic examines the poem’s antithetic images of light and darkness.','评论者分析了诗中光与暗相对照的意象。'),('The two characters express antithetic views of duty.','这两个人物表达了彼此对立的责任观。'),sources=['https://www.etymonline.com/word/antithetic','https://www.merriam-webster.com/dictionary/antithetic']),
E('antithetical','/ˌæntɪˈθetɪkəl/','截然相反的；根本冲突的','不是小地方不一样，而是两种原则朝相反方向走。','希腊 antithetikos 经拉丁化形态并用 -al 进入英语；英语中此长形式早于 antithetic 的已知常用记录。',ANTIA,'常用 antithetical to：一种做法与某项价值根本不相容。它可以说立场、目标或原则，不一定是在写工整的对偶句。','antithetical to freedom；antithetical values；two antithetical approaches。','different 只是不同；antithetical 常指出两者无法同时按原样成立的冲突。',('Secret decision-making is antithetical to the transparency the group promises.','秘密决策与这个团体承诺的透明度根本冲突。'),('The two designs reflect antithetical ideas about public space.','这两项设计体现了对公共空间截然相反的看法。'),sources=['https://www.etymonline.com/word/antithetical','https://www.oxfordlearnersdictionaries.com/definition/english/antithetical']),
E('parenthesis','/pəˈrenθəsɪs/','插入语；圆括号；插曲','话说到一半，旁边插入一小段补充，再回到原来的主线。','希腊 para- + en- + tithenai 的复合动词形成 parenthesis，再经拉丁语、法语传入。现代不按 parent“父母”拆。',PAREN,'单个符号可叫 a parenthesis；一对通常说 parentheses。in parentheses 是放在圆括号里。插入语也可用破折号或逗号标出，因此语法上的 parenthesis 不限于括号符号。','in parentheses；an opening parenthesis；a brief parenthesis。','parenthesis 单数结尾 /sɪs/；parentheses 复数结尾 /siːz/。brackets 的具体符号范围随英美语境变化。',('Put the publication year in parentheses after the author’s name.','把出版年份放在作者姓名后面的圆括号里。'),('His comment about the weather was a brief parenthesis in a serious discussion.','他那句关于天气的话，是严肃讨论中的一个小插曲。'),sources=['https://www.etymonline.com/word/parenthesis','https://www.oxfordlearnersdictionaries.com/definition/english/parenthesis']),
E('parenthetic','/ˌpærənˈθetɪk/','插入式的；附带说明的','像在正文旁边轻轻补一句，不改变原话的主干。','与希腊 parenthetos、中世纪拉丁 parentheticus 相连；词典也有从 parenthetical 缩短的解释，不强定单一路线。',PARENA,'a parenthetic remark 是附带插话；可以夹在括号、逗号或破折号之间。它描述这句话在结构中的地位，不表示内容一定无关紧要。','a parenthetic remark；a parenthetic phrase；a parenthetic reference。','parenthetic 与 parenthetical 意思接近；后者在当代一般书面语中更常见。',('She added a parenthetic remark about the unusual spelling.','她附带说了一句，解释那个不寻常的拼写。'),('The editor removed a long parenthetic phrase from the sentence.','编辑删掉了句子中一段很长的插入语。'),sources=['https://en.wiktionary.org/wiki/parenthetic#English','https://www.merriam-webster.com/dictionary/parenthetic']),
E('parenthetical','/ˌpærənˈθetɪkəl/','插入的；括号内的；附带的','主句继续向前走，旁边挂着一小段解释。','经中世纪拉丁 parentheticus 等材料形成，接希腊 parenthetos；不是现代 parenthesis 原样加 -al。',PARENA,'parenthetical information 是插进去的补充信息。学术写作的 parenthetical citation 常是正文括号里的文献引用，而不是脚注。','a parenthetical comment；parenthetical information；a parenthetical citation。','incidental 强调附带、次要；parenthetical 更强调插入主句或主线的方式。',('The parenthetical comment explains why the date is uncertain.','括号中的补充说明解释了日期为何不确定。'),('Use parenthetical citations rather than footnotes for these references.','这些文献请用正文括号引用，而不要放在脚注里。'),sources=['https://www.etymonline.com/word/parenthetical','https://www.oxfordlearnersdictionaries.com/definition/english/parenthetical']),
E('parenthetically','/ˌpærənˈθetɪkli/','插一句地；附带地；放在括号内','把主线暂放一边，说一句补充的话。','parenthetical + -ly；常见读法压缩为 /θetɪkli/。',PARENA+[['英语 parenthetical → parenthetically','附带的 → 附带地说、写']],'可以说 add parenthetically，也可放句首 Parenthetically, ...，作用接近较正式的“顺便插一句”。它不一定真的要求加括号。','remark parenthetically；add parenthetically；mention parenthetically。','by the way 更口语；parenthetically 常见于较正式的说明与评论。',('She mentioned parenthetically that the original letter had been lost.','她附带提到，原信已经遗失。'),('The editor gives the alternative spelling parenthetically.','编辑把另一种拼写放在括号内给出。'),sources=['https://www.merriam-webster.com/dictionary/parenthetically','https://www.collinsdictionary.com/dictionary/english/parenthetically']),
E('epithet','/ˈepɪθet/','称号；描述性别称；辱称〔依语境〕','给名字旁边贴上一句描述，让人一听就想到某个特点。','希腊 epi-“加在上面” + tithenai → epitheton“附加的词”，经拉丁语和法语进入英语。',TH+[['希腊语 epitithenai → epitheton','加在上面 → 附加的描述'],['拉丁语 epitheton / epithetum → 法语 épithète','修饰、描述性称呼'],['英语 epithet','别称、称号；有时是辱称']],'“the Great”一类称号可叫 epithet；racial epithet 则是带种族侮辱意味的称呼。是否褒义、贬义，要看具体内容，不能把这个词本身固定翻成骂人话。','a descriptive epithet；a derogatory epithet；earn an epithet。','nickname 是昵称或绰号，范围更生活化；epithet 强调加在对象上的描述或标签。',('The ruler became known by the epithet “the Bold.”','这位统治者以“勇敢者”的称号为人所知。'),('The editor removed a derogatory epithet from the article.','编辑删掉了文章中的一个贬损称呼。'),sources=['https://www.etymonline.com/word/epithet','https://www.oxfordlearnersdictionaries.com/definition/english/epithet']),
E('anathema','/əˈnæθəmə/','极其厌恶的事物；诅咒、绝罚〔宗教历史〕','某人一听就坚决排斥，觉得“这根本不能接受”。','希腊 ana- 与“放置”组成献上、立起之意；相关名词后来在宗教语境产生咒诅、被排斥的含义，经晚期拉丁语传入。',TH+[['希腊语 anatithenai → anathema','献上、置于神前 → 献祭物；宗教语境下又有咒诅义'],['晚期拉丁语 anathema → 英语 anathema','咒诅、绝罚 → 极端排斥的事物']],'现代常用 something is anathema to someone，意为某事是对方深恶痛绝的。这里通常不加 a。历史宗教用法也能作可数名词，指一次诅咒或绝罚。','be anathema to；regard something as anathema；pronounce an anathema。','dislike 只是一般不喜欢；anathema 强调价值上强烈排斥。',('Waste is anathema to a cook who grew up with very little.','对一位在物资匮乏中长大的厨师来说，浪费是绝不能接受的。'),('The historian explains how the council used the term anathema.','历史学家解释了那次会议如何使用“绝罚”这个词。'),sources=['https://www.etymonline.com/word/anathema','https://www.oxfordlearnersdictionaries.com/definition/english/anathema']),
E('anathematic','/əˌnæθəˈmætɪk/','诅咒的；令人强烈排斥的〔少用〕','带着“把它排除出去”的强烈反感或咒诅语气。','希腊 anathema 的词干 anathemat- + 英语 -ic；中间 -mat- 来自古典词干，不是随意多出的字母。',TH+[['希腊语 anathema，词干 anathemat-','献上之物；咒诅、受排斥之物'],['英语 anathemat- + -ic → anathematic','具有咒诅、强烈排斥性质的']],'它多见于旧文或正式评论，可修饰诅咒性语言，也可说某观念为人所强烈排斥。普通表达通常直接用 be anathema to。','anathematic language；an anathematic denunciation；anathematic to。','anathema 是名词或名词式表语；anathematic 是较少用的形容词。',('The pamphlet uses anathematic language against every compromise.','这本小册子用近乎咒骂的语言反对一切妥协。'),('Such compulsory conformity was anathematic to the writer.','这种强制一致的做法令这位作家极其反感。'),sources=['https://www.merriam-webster.com/dictionary/anathematic','https://en.wiktionary.org/wiki/anathematic#English']),
E('prosthesis','英 /prɒsˈθiːsɪs/；美 /prɑːsˈθiːsɪs/','假体；义肢等人工替代物','给身体补上一个替代部件，帮助恢复形状或功能。','希腊 pros-“加上” + thesis“放置”，完整词经拉丁语传入；并非 pro-“赞成” + thesis“论文”。',[['希腊 pros 向、加上；tithenai 放置', '并列构成添加的动作'], ['希腊 prostithenai → prosthesis → 晚期拉丁 prosthesis', '添加、附加'], ['英语 prosthesis：先语法添音，后医学添加替代物', '十六世纪添入字母或音节；十八世纪用于给身体补入人工部件']],'既可指外部义肢，也可指体内人工关节等假体，不能只翻成假腿。复数 prostheses。旧语言学材料中它也有添音义，与 prothesis 用法有交叠。','a limb prosthesis；a dental prosthesis；fit a prosthesis。','implant 强调植入体内；prosthesis 强调替代身体部分，两者范围有交叉。',('The technician adjusted the prosthesis for a more comfortable fit.','技术人员调整了假体，让佩戴更舒适。'),('The diagram shows the components of a hip prosthesis.','示意图展示了髋关节假体的组成部分。'),sources=['https://www.etymonline.com/word/prosthesis','https://www.merriam-webster.com/dictionary/prosthesis']),
E('prosthetic','英 /prɒsˈθetɪk/；美 /prɑːsˈθetɪk/','假体的；义肢的；假体〔名词〕','说明这是用来补替身体部件的，而不是原有组织。','经近代拉丁 prostheticus，接希腊 prosthetikos“添加的”；现代可与 prosthesis 对照，但形容词有独立借入路线。',[['希腊 pros 向、加上；tithenai 放置', '共同构成添加的词族'], ['希腊 prostithenai → prosthetikos → 拉丁化 prostheticus', '用来添加的'], ['英语 prosthetic：早期语法添音义；后用于假体', '形容词有独立借入路线，并非只由英语 prosthesis 加后缀']],'prosthetic hand 是假手；prosthetic fitting 是适配假体。作名词时也能指假体；电影化妆中的 prosthetics 常指附加的仿真身体部件，不是在医疗中替代失去的器官。','a prosthetic limb；a prosthetic eye；prosthetic makeup。','artificial 更宽泛；prosthetic 指向身体部件的替代或仿制。',('He learned to control the fingers of his prosthetic hand.','他学会了控制假手的手指。'),('The actor wore prosthetic makeup to change the shape of his nose.','演员借助特效假体化妆改变了鼻子的形状。'),sources=['https://www.etymonline.com/word/prosthetic','https://www.oxfordlearnersdictionaries.com/definition/english/prosthetic']),
E('prothesis','英 /ˈprɒθəsɪs/；美 /ˈprɑːθəsɪs/','词首添音；圣餐预备礼或预备处〔礼仪〕','语音里是在词前多出一个音；礼仪里是先把将用的物品摆好。','语法义的拉丁 prothesis 常解释为 prosthesis 的变体；礼仪义另接希腊 prothesis“摆在前面”。两支都远接“放置”，不能混成一条。',[['希腊语 tithenai；pros-“加上” / pro-“在前”','放置；形成两支相关词'],['语法：prosthesis → 拉丁变体 prothesis；礼仪：希腊 prothesis','添音；预先摆置'],['英语 prothesis','词首添音；圣餐预备礼或预备处']],'语音例子可看拉丁 status 到古法语 estat 开头多出的 e：这是发音演变，不是为改变意思加前缀。宗教义出现在东部基督教礼仪材料中。','vowel prothesis；prothesis before a consonant cluster；the rite of prothesis。','epenthesis 常谈词内插音；prothesis 专说词首添音。prosthesis 的现代常见义是假体。',('The lecturer used the change from status to estat to illustrate prothesis.','讲师用 status 变成 estat 的过程说明词首添音。'),('The guide describes the small table used for the prothesis.','指南介绍了用于圣餐预备礼的小桌。'),sources=['https://www.merriam-webster.com/dictionary/prothesis','https://www.etymonline.com/word/prothesis']),
E('prothetic','/prəˈθetɪk/','词首添音的','一个音出现在原来词形的最前面，帮助形成新的发音形式。','与希腊 prothetikos 相连，远接 pro-“在前” + tithenai；可与英语 prothesis 对照，不必假定英语名词先派生此形容词。',TH+[['希腊语 prothetos / prothetikos','置于前面的'],['英语 prothetic','与词首添音有关的']],'a prothetic vowel 就是添在词首的元音。它描述声音变化的位置，不是说这个元音本来就是词根的一部分。','a prothetic vowel；a prothetic consonant；prothetic addition。','prothetic 看词首添音；prosthetic 多用于假体，两词拼写很接近。',('The initial e in the borrowed form is a prothetic vowel.','借入形式开头的 e 是一个词首增添的元音。'),('The study compares prothetic vowels in several dialects.','这项研究比较了几种方言中的词首添入元音。'),sources=['https://www.merriam-webster.com/dictionary/prothetic','https://www.collinsdictionary.com/dictionary/english/prothesis','https://en.wiktionary.org/wiki/prothetic#English']),
E('epenthesis','/ɪˈpenθəsɪs/','插音；增音〔语音学〕','发一个词时，原本相邻的声音中间多出一个音。','希腊 epi- + en- + tithenai → epenthesis“插入”，经晚期拉丁语借入。',TH+[['希腊语 epentithenai → epenthesis','插入里面 → 插入'],['晚期拉丁语 epenthesis → 英语 epenthesis','语音中的增音、插音']],'例如某些说法把 athlete 中 /θl/ 之间加进弱元音，形成接近 /ˈæθəliːt/ 的读法。这个术语描述声音现象；不同研究对是否包含词首、词尾增音的范围可能不同。','vowel epenthesis；consonant epenthesis；epenthesis in consonant clusters。','elision 是省掉声音；epenthesis 是加进声音。',('The recording shows vowel epenthesis between the two consonants.','录音显示，两个辅音之间加入了一个元音。'),('The class discussed epenthesis as a regular feature of the dialect.','课堂讨论了作为该方言固定特征的插音现象。'),sources=['https://www.merriam-webster.com/dictionary/epenthesis','https://en.wiktionary.org/wiki/epenthesis#English']),
E('epenthetic','/ˌepənˈθetɪk/','插入的；增音的〔语音学〕','多出来的那个音是在发音过程中添入的。','借用希腊 epenthetikos“插入的”一系形容词材料；现代和 epenthesis 成对使用。',TH+[['希腊语 epenthetos → epenthetikos','插进来的 → 插入的'],['英语 epenthetic','属于插音现象的']],'an epenthetic vowel 是添入的元音；an epenthetic consonant 是添入的辅音。说它是 epenthetic，只说明历史或分析上的添加地位，不等于批评说话者念错。','an epenthetic vowel；an epenthetic schwa；an epenthetic consonant。','inherent 是原有的；epenthetic 指在声音组合中添入的。',('An epenthetic schwa separates the consonants in this pronunciation.','这种读法在两个辅音之间插入了一个弱元音。'),('The researcher marked the epenthetic consonant in brackets.','研究者用括号标出了添入的辅音。'),sources=['https://www.merriam-webster.com/dictionary/epenthetic','https://en.wiktionary.org/wiki/epenthetic#English']),
]
THECA=TH+[['希腊语 thēkē → 拉丁语 theca','放东西的盒、套、容器'],['新拉丁语 theca → 英语 theca','生物体的壳、鞘或囊状结构']]
HYPC=TH+[['希腊语 hypotithenai → hypothēkē','放在下面作凭据 → 担保、抵押'],['晚期拉丁语 hypotheca','担保、抵押权']]
W += [
E('bibliotheca','/ˌbɪbliəˈθiːkə/','图书馆；藏书集〔较古雅〕','把书集中安放、保存起来的地方或那一批藏书。','希腊 biblio-“书” + thēkē“储放处”，经拉丁 bibliotheca 借入。',[['希腊语 biblion + thēkē → bibliothēkē','书 + 存放处 → 藏书处'],['拉丁语 bibliotheca → 英语 bibliotheca','图书馆、藏书集']],'当代日常通常用 library；bibliotheca 常见于历史名称、拉丁书名和古雅描述。某些书名也用它表示资料或作品的汇集。','a private bibliotheca；the monastery’s bibliotheca；a bibliotheca of manuscripts。','bibliography 是书目或文献清单；bibliotheca 说藏书处、藏书集或汇编本身。',('The catalogue lists the manuscripts once held in the monastery’s bibliotheca.','目录列出了修道院藏书库曾经收藏的手稿。'),('The scholar built a small bibliotheca devoted to classical medicine.','这位学者建立了一座专藏古典医学著作的小型书库。'),sources=['https://www.merriam-webster.com/dictionary/bibliotheca','https://en.wiktionary.org/wiki/bibliotheca#English']),
E('Themis','/ˈθiːmɪs/','忒弥斯；希腊神话中体现神圣秩序、法律与习俗的女神','把“事情应当怎样安排、规则应当怎样确立”拟成一个神祇形象。','由希腊专名 Themis 借入；其普通名词 themis 指既定秩序、神圣规则，通常与 tithenai“设定、放置”相联系。',[['希腊语 tithenai 与 themis 的传统词源联系','设定 → 已确立的秩序、规则'],['希腊语 Themis → 英语 Themis','规则、秩序的人格化女神']],'这是专有名词，首字母大写。艺术、神话研究和机构名称中都可能出现；不要因为现代正义女神图像相近，就把所有持天平雕像都认定为同一位神。','the goddess Themis；a statue of Themis；Themis in Greek mythology。','themis 的希腊古义涉及神圣秩序；英语 theme“主题”是另一名词支线，不能互换。',('The lecture introduced Themis as a figure of divine order.','讲座介绍了体现神圣秩序的女神忒弥斯。'),('The museum label identifies the figure as Themis.','博物馆标签把这尊人物像标为忒弥斯。'),sources=['https://en.wiktionary.org/wiki/Themis#English','https://www.perseus.tufts.edu/hopper/morph?l=qe%2Fmis&la=greek']),
E('theca','/ˈθiːkə/','壳；鞘；囊状结构〔生物学〕','像包在外面的小盒或套，把某种组织、细胞或内容物围起来。','希腊 thēkē“盒、容器”，经拉丁语和新拉丁生物术语进入英语。',THECA,'不同领域指不同结构，例如卵巢滤泡周围的卵泡膜，或花药中的药室单位。只凭这个词不能认定它们是同一种组织；复数 thecae。','follicular theca；theca cells；an anther theca。','theca 强调套、囊、壳的形态；具体是膜、组织还是外壳，要看所修饰的器官。',('The diagram labels the theca surrounding the ovarian follicle.','示意图标出了围绕卵巢滤泡的卵泡膜。'),('The botanist examined the structure of each anther theca.','植物学家检查了每个花药药室单位的结构。'),sources=['https://www.merriam-webster.com/dictionary/theca','https://en.wiktionary.org/wiki/theca#English']),
E('nomothetic','英 /ˌnɒməˈθetɪk/；美 /ˌnɑːməˈθetɪk/','寻求一般规律的；制定法则的','把很多个案放在一起，问：它们背后有没有共同规律？','希腊 nomos“规则、法” + -thetēs“设立者”形成 nomothetikos，经新拉丁 nomotheticus 传入。',TH+[['希腊语 nomos + -thetēs → nomothetikos','法律 + 设立者 → 立法的'],['新拉丁语 nomotheticus → 英语 nomothetic','制定法则的 → 寻求普遍规律的']],'研究方法中 a nomothetic approach 侧重从许多对象找共同模式；并不保证已发现绝无例外的定律。常与重视个案独特性的 idiographic 对照。','a nomothetic approach；nomothetic research；nomothetic explanations。','nomothetic 看跨个案的一般性；idiographic 细看一个对象的独特历程。',('The study takes a nomothetic approach to patterns of migration.','这项研究采用寻求一般规律的方法研究迁移模式。'),('Her course compares nomothetic research with detailed individual case studies.','她的课程比较一般规律研究与细致的个案研究。'),sources=['https://www.merriam-webster.com/dictionary/nomothetic','https://www.collinsdictionary.com/dictionary/english/nomothetic']),
E('hypothec','英 /haɪˈpɒθɪk/；美 /haɪˈpɑːθɪk/','财产上的担保权、抵押权〔特定法域用语〕','财产用来为一项义务作担保；债权人因此取得针对这项财产的权利。','希腊 hypo-“在下” + tithenai“放置”形成 hypothēkē“担保”，经晚期拉丁 hypotheca，部分路线有法语 hypothèque。',HYPC+[['晚期拉丁语 hypotheca；亦经法语 hypothèque → 英语 hypothec','财产作为担保所产生的权利']],'常见于罗马法、苏格兰法和魁北克等相关材料。它不是债务金额本身；具体可担保哪些财产、怎样实现权利，要看所说法域，不能把旧时规则套到所有地方。','a hypothec over property；a conventional hypothec；a landlord’s hypothec。','hypothesis 是研究假设；hypothec 是财产担保用语。两者都远接“放在下面”，现代用途却不同。',('The textbook compares a hypothec with other forms of security.','教材比较了抵押权与其他担保形式。'),('The document describes the property subject to the hypothec.','文件描述了该抵押权所涉及的财产。'),sources=['https://www.collinsdictionary.com/dictionary/english/hypothec','https://www.merriam-webster.com/dictionary/hypothec']),
E('hypothecate','英 /haɪˈpɒθɪkeɪt/；美 /haɪˈpɑːθəkeɪt/','以财产担保；把税收指定专用；假设〔少见义〕','担保义是“拿这项财产作后盾”；财政义则是“把这笔收入划给这个用途”。','法律义接中世纪拉丁 hypothecare / hypothecatus；另有“假设”义，联系希腊 hypothēkē“建议、设想”，不要解释成抵押后来变成猜测。',[*HYPC,['中世纪拉丁语 hypothecare / hypothecatus → 英语 hypothecate','以财产作担保；另有指定税收用途义'],['另一路：希腊 hypothēkē“设想” → 英语 hypothecate','较少用的“假设”；不从担保义演变']],'法律常用义强调设定担保而不因这一动作交出占有或所有权。英国公共财政语境可说把某项税收专用于某项支出。表示“假设”时，hypothesize 更常见。','hypothecate assets；hypothecate revenue for；hypothecated taxes。','mortgage 是更熟悉的相关担保词；hypothecate 还可谈收入指定用途，不能见词就译成房贷。',('The agreement allows the company to hypothecate specified assets as security.','协议允许公司以指定资产提供担保。'),('The proposal would hypothecate the new tax revenue for public transport.','这项提案拟将新税收收入专用于公共交通。'),sources=['https://www.merriam-webster.com/dictionary/hypothecate','https://www.collinsdictionary.com/dictionary/english/hypothecate']),
E('hypothecation','英 /haɪˌpɒθɪˈkeɪʃən/；美 /haɪˌpɑːθəˈkeɪʃən/','设定财产担保；税收专用','把资产与担保义务联系起来，或把一笔税收与特定支出绑定。','法律名词借自中世纪拉丁 hypothecatio，由 hypothecare 的分词词干形成；现代可与 hypothecate 对照，并非一定从英语动词新造。',HYPC+[['中世纪拉丁语 hypothecare → hypothecatio','设定担保 → 担保行为'],['英语 hypothecation','财产担保；税收用途的指定']],'资产语境里重点是担保安排；财政讨论里重点是专项税收或专款用途。读句子时先看对象是 assets 还是 tax revenue，再决定译法。','the hypothecation of assets；tax hypothecation；a hypothecation agreement。','allocation 只是分配用途；税收 hypothecation 更具体地把某项收入限定或指定给某种用途。',('The report records the hypothecation of several company assets.','报告记录了公司若干资产用于担保的情况。'),('The debate focused on the hypothecation of fuel-tax revenue.','辩论围绕燃油税收入是否专款专用展开。'),sources=['https://www.merriam-webster.com/dictionary/hypothecation','https://www.collinsdictionary.com/dictionary/english/hypothecate']),
E('enthesis','/ɪnˈθiːsɪs/','附着点；肌腱或韧带等与骨连接的部位','像绳索固定到坚硬支架上的接口，是软组织把拉力传到骨头的连接处。','直接采用希腊 enthesis“放入、插入”：en-“里面” + tithenai。',TH+[['希腊语 entithenai → enthesis','放进去 → 插入、附着'],['英语 enthesis','肌腱、韧带等在骨上的附着处']],'它指解剖连接区域，不是整条肌腱，也不只是一粒几何上的点。复数 entheses；相关炎症词是 enthesitis，不能与旧词 enthetic 混用。','the tendon enthesis；the Achilles enthesis；an enthesis on the bone。','tendon 是肌腱整体；enthesis 是其与骨连接的部位。',('The scan shows changes near the tendon’s enthesis.','扫描显示肌腱附着点附近出现了变化。'),('The diagram marks the enthesis where the ligament joins the bone.','图中标出了韧带与骨连接的附着处。'),sources=['https://en.wiktionary.org/wiki/enthesis#English','https://pubmed.ncbi.nlm.nih.gov/16637873/']),
E('enthetic','/enˈθetɪk/','由外部传入、接种传入的〔旧医学用语〕','旧时用来强调：病原从身体外面被带入了身体。','来自希腊 enthetikos，接 entithenai“放进”。与 enthesis 同属“放入”支线，但不是现代附着点的通用形容词。',TH+[['希腊语 entithenai → enthetikos','放进去 → 适于植入、传入的'],['英语 enthetic','从外部传入的，尤用于旧医学疾病分类']],'读旧医书时可能看到 enthetic disease，常涉及经接种、接触等由外传入的病。这不是当代泛指一切传染病的首选说法，也不是“肌腱附着点的”。','an enthetic disease；enthetic infection；the old category “enthetic”。','infectious 是现代常见的感染性；enthetic 是带历史分类色彩的少用词。',('The old textbook classifies the illness as an enthetic disease.','那本旧教材把这种病归为由外部传入的疾病。'),('The historian explains what nineteenth-century doctors meant by enthetic.','历史学家解释了十九世纪医生所说的 enthetic 是什么意思。'),sources=['https://www.collinsdictionary.com/dictionary/english/enthetic','https://en.wiktionary.org/wiki/enthetic#English']),
E('epitheca','构词参考读法 /ˌepɪˈθiːkə/','上壳；硅藻较大的半壳〔等生物结构〕','硅藻的外壳像套合的小盒：较大的半边套在较小半边外面。','epi-“在上、覆盖” + theca“壳”；是采用希腊构词材料形成的生物术语。',TH+[['希腊语 epi + thēkē','覆盖在上 + 壳、容器'],['新拉丁构词 epitheca → 英语 epitheca','覆盖另一半的壳；硅藻上壳']],'硅藻中 epitheca 是较大的半壳，与 hypotheca 套合。“上”是结构名称，不表示观察时它一定朝天空。某些其他藻类的 epitheca 定义另有体系，需看具体类群。','the diatom epitheca；the larger epitheca；epitheca and hypotheca。','epitheca 是硅藻套在外侧的较大半壳；hypotheca 是较小半壳。',('The epitheca overlaps the smaller half of the diatom shell.','硅藻上壳套在较小的半壳外面。'),('The student labelled the epitheca and hypotheca separately.','学生分别标出了上壳和下壳。'),sources=['https://diatoms.org/glossary/epitheca','https://en.wiktionary.org/wiki/epitheca#English']),
E('apothecium','/ˌæpəˈθiːʃiəm/，也读 /ˌæpəˈθiːsiəm/','子囊盘〔真菌学〕','像张开的小杯或小盘，产生孢子的子囊排在露出的表面。','新拉丁 apothecium 采用希腊 apothēkē“储藏处” + -ium；不是直接把现代英语 thecium 随便加 apo-。',TH+[['希腊语 apothēkē','储藏处'],['新拉丁语 apothecium','以“储藏处”命名的真菌生殖结构'],['英语 apothecium','表面暴露子囊的盘状或杯状子实体']],'许多地衣和真菌都有这类结构，成熟时产孢层向外露出。复数 apothecia。看到 cup 只是帮助理解外形；并非每个都长得像圆整的小碗。','a cup-shaped apothecium；the apothecium surface；mature apothecia。','perithecium 通常是有孔口的瓶状结构；apothecium 以开放、暴露的产孢表面为特点。',('The lichen bears a small orange apothecium.','这株地衣上长着一个橙色的小子囊盘。'),('Under the microscope, asci were visible on the apothecium’s exposed surface.','在显微镜下，可以看到子囊盘裸露表面上的子囊。'),sources=['https://www.merriam-webster.com/dictionary/apothecium','https://www.anbg.gov.au/fungi/ascomycetes-basidiomycetes.html']),
E('pseudothecium','构词参考读法 /ˌsuːdəʊˈθiːʃiəm/；美式 /ˌsuːdoʊˈθiːʃiəm/','假囊壳〔真菌学〕','外表像一只小囊壳，但内部子囊的形成方式和结构有自己的特点。','pseudo-“类似而非真正同类” + thecium；这里的“假”是分类对照，不是说真菌伪造了器官。',TH+[['希腊语 thēkē / thēkion → 新拉丁语 thecium','容器、小囊'],['pseudo- + thecium → 英语 pseudothecium','貌似子囊壳的另一类子实体']],'常呈腔室状，子囊在子座组织的腔中发育，典型子囊具双层壁。与 perithecium 外形相像，判断时要看发育和内部结构；复数 pseudothecia。','a fungal pseudothecium；bitunicate asci in a pseudothecium；mature pseudothecia。','apothecium 像开放的小盘；pseudothecium 是更封闭的腔状结构，不能只凭“装孢子”混为一类。',('The section shows asci developing inside a pseudothecium.','切片显示子囊在假囊壳内部发育。'),('The students compared a pseudothecium with an open apothecium.','学生们比较了假囊壳和开放的子囊盘。'),sources=['https://en.wiktionary.org/wiki/pseudothecium#English','https://llufb.llu.lv/LLU-studiju-materiali/LF/General_plant_pathology_LLU_2021.pdf']),
E('thecium','构词参考读法 /ˈθiːʃiəm/，亦可按 -cium 读 /ˈθiːsiəm/','子实层；子囊盘内部菌丝层〔旧真菌学用语〕','旧文献用来指真菌小“囊室”中的产孢层或内部组织。','新拉丁 thecium 接希腊 thēkion，后者是 thēkē“容器”的指小形式；并非 the + cium 两个英语词。',TH+[['希腊语 thēkē → thēkion','容器 → 小容器'],['新拉丁语 thecium → 英语 thecium','真菌学旧称：子实层或相关内部层']],'现代阅读更常遇到 hymenium 表示子实层。旧作者对 thecium 所覆盖的组织范围并不完全一致，因此读图例时应按该文定义，别只靠一个固定中文标签。','the thecium of a lichen；thecium in older descriptions；thecium and hymenium。','theca 多指囊、鞘、壳；thecium 在旧真菌学里可指其中的组织层，两者不能机械互换。',('The old description uses thecium for the spore-bearing layer.','旧描述用 thecium 指产生孢子的组织层。'),('The translator checked how the author defined thecium before choosing a Chinese term.','译者在选择中文术语前，核对了作者如何界定 thecium。'),sources=['https://www.mobot.org/mobot/latindict/keyDetail.aspx?keyWord=thecium','https://en.wiktionary.org/wiki/thecium#English']),
]
O=[['拉丁语 optare','选择、希望；更早来源有争议']]
OPTION=O+[['拉丁语 optio → 法语 option','选择、选择权'],['英语 option','选择余地；可选项；特定选择权']]
AD=O+[['拉丁语 ad- + optare → adoptare','为自己选择 → 接纳、收养']]
ADOPT=AD+[['英语 adopt 的近源有不同解释','从 adoption 逆构，或借古法语 adopter / 拉丁 adoptare'],['英语 adopt','收养；正式采纳、采用']]
ADOPTION=AD+[['拉丁语 adoptio → 古法语 adopcion；亦可直接借拉丁语','接纳为家庭成员'],['中古英语 adopcioun → adoption','收养；采纳、采用']]
CO=O+[['拉丁语 com- + optare → cooptare','一起选择 → 选入团体'],['英语 coopt','增选、吸收成员 → 收编、挪用']]
W += [
E('option','英 /ˈɒpʃən/；美 /ˈɑːpʃən/','选择；选项；选择权；期权','面前有几条可走的路，其中一条就是一个 option。','经法语 option 接拉丁 optio；英语 option 早于 opt，不能把“看起来 opt + -ion”当成实际借入顺序。',OPTION,'have no option 是没有选择余地；a cheaper option 是更便宜的方案。金融期权给持有人按约定条件买或卖的权利，通常并非必须执行；具体权利取决于合约。动词 option 也可指取得作品等的选用权。','consider your options；have the option of；an option to buy。','choice 可以强调作决定的动作；option 常强调摆在面前的方案或保留的选择权。',('Taking the train is our cheapest option.','坐火车是我们最便宜的选择。'),('The contract gives the tenant an option to renew the lease.','合同赋予租户续租的选择权。'),sources=['https://www.etymonline.com/word/option','https://www.oxfordlearnersdictionaries.com/definition/english/option','https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins-63']),
E('opt','英 /ɒpt/；美 /ɑːpt/','选择；决定采用','考虑过可选的路之后，明确挑中其中一条。','借自法语 opter，源于拉丁 optare；英语动词本身比 option 晚进入常用记录。',O+[['法语 opter → 英语 opt','选择 → 作出选择']],'用 opt for + 名词，或 opt to + 动词。opt in 是选择参加，opt out 是选择退出或不参加；不能照 choose 的语法直接说 opt the train。','opt for a simpler design；opt to stay；opt out of a scheme。','choose 可直接接事物；opt 常配 for 或 to，更突出作选择的决定。',('We opted for the smaller room because it was quieter.','我们选了较小的房间，因为那里更安静。'),('She opted to take the exam in June.','她决定六月参加考试。'),sources=['https://www.etymonline.com/word/opt','https://www.oxfordlearnersdictionaries.com/definition/english/opt']),
E('optional','英 /ˈɒpʃənəl/；美 /ˈɑːpʃənəl/','可选的；非必需的','你可以选它，也可以不选；少了它不一定妨碍完成要求。','option + -al；在英语名词基础上形成表示性质的形容词。',OPTION+[['英语 option + -al → optional','有选择余地 → 可自行选择的']],'an optional course 是选修课；optional equipment 是额外可选配置。optional 不自动等于免费，也不意味着没人推荐，只说明不是规定必须。','an optional extra；an optional course；attendance is optional。','compulsory / mandatory 是必须；optional 是由你选择。',('Attendance at the evening session is optional.','晚间场次可以自愿参加。'),('The camera comes with an optional external microphone.','这款相机可选配外接麦克风。'),sources=['https://www.etymonline.com/word/optional','https://www.oxfordlearnersdictionaries.com/definition/english/optional']),
E('optionally','英 /ˈɒpʃənəli/；美 /ˈɑːpʃənəli/','可选择地；按需','这一步留给使用者决定，要做也行，不做也行。','optional + -ly；用副词说明一个步骤或配置是否必须。',OPTION+[['英语 optional → optionally','可选的 → 可以选择这样做']],'食谱、软件说明和操作指南里常见。句首 Optionally, ... 大致是“如果愿意，还可以……”。它说明该动作可选，不是说动作做得随便。','optionally add；optionally include；optionally available。','optionally 是可以不做；alternatively 是可以改做另一件事，两者着眼点不同。',('Optionally, add a little lemon juice before serving.','上桌前可按喜好加一点柠檬汁。'),('The app can optionally save a local copy of each file.','应用可以按需保存每个文件的本地副本。'),sources=['https://www.merriam-webster.com/dictionary/optionally','https://en.wiktionary.org/wiki/optionally#English']),
E('optionality','英 /ˌɒpʃəˈnæləti/；美 /ˌɑːpʃəˈnæləti/','可选性；保留选择的余地','现在不把所有门都关死，让以后仍能根据情况换路。','optional + -ity；把可选择的性质抽象成名词。',OPTION+[['英语 optional + -ity → optionality','可选的 → 可选性、选择空间']],'语言学里可以讨论某成分是否可省；商业策略里 retain optionality 是保留后续选择。这个词较抽象，日常说 keep our options open 往往更自然。','preserve optionality；the optionality of a feature；strategic optionality。','flexibility 是灵活适应；optionality 更聚焦手里还保留哪些选择。',('Renting a smaller office preserves optionality as the team grows.','先租一间较小办公室，能让团队扩张时保留更多选择。'),('The paper examines the optionality of the pronoun in these sentences.','论文研究这些句子里的代词是否可以省略。'),sources=['https://www.merriam-webster.com/dictionary/optionality','https://en.wiktionary.org/wiki/optionality#English']),
E('nonoptional','英 /ˌnɒnˈɒpʃənəl/；美 /ˌnɑːnˈɑːpʃənəl/','非可选的；必须具备或执行的','这部分没有“跳过”按钮，必须满足要求。','non- 否定 + optional；常见于技术、管理或规则说明。',OPTION+[['英语 optional → nonoptional','可选 → 不可选择省略的']],'a nonoptional field 是必须提供的字段；nonoptional training 是必须参加的培训。它强调“没有选择空间”，一般说明里 required 或 mandatory 常更直接。','a nonoptional requirement；nonoptional fields；nonoptional training。','optional 可省或可不选；nonoptional 必须保留或完成，并非“不推荐选”。',('Safety training is a nonoptional part of the programme.','安全培训是项目中必须完成的部分。'),('The form marks all nonoptional fields with an asterisk.','表单用星号标出所有必填字段。'),sources=['https://en.wiktionary.org/wiki/nonoptional#English','https://www.merriam-webster.com/dictionary/nonoptional']),
E('adopt','英 /əˈdɒpt/；美 /əˈdɑːpt/','收养；采纳；采用；采取','把原先不属于自己的某人、方法或立场，正式接纳进自己的生活或做法里。','拉丁 ad-“向自己” + optare“选择”。英语近源有从 adoption 逆构、借法语 adopter 或直接借拉丁 adoptare 等解释。',ADOPT,'adopt a child 是建立收养关系；adopt a method 是开始采用一种方法；adopt a calm tone 是采取平静语气。共同点是接纳、选择并用起来。','adopt a child；adopt a policy；adopt an approach；adopt a tone。','adapt 是调整以适应；adopt 是接纳、采用。先 adopt a method，再 adapt it to your needs。',('They adopted a child several years ago.','他们几年前收养了一个孩子。'),('The team adopted a simpler method for checking the results.','团队采用了更简单的方法来核对结果。'),sources=['https://www.etymonline.com/word/adopt','https://www.oxfordlearnersdictionaries.com/definition/english/adopt']),
E('adoption','英 /əˈdɒpʃən/；美 /əˈdɑːpʃən/','收养；采纳；采用、普及过程','接纳这件事本身，以及某个方法逐渐被用起来的过程。','经古法语 adopcion 或直接接拉丁 adoptio；英语名词早于动词 adopt 的记录，不能把历史一律画成 adopt 加后缀。',ADOPTION,'adoption of a child 说收养；adoption of a policy 说正式采纳政策；technology adoption 关注人们实际开始使用技术，未必等于购买一次设备。','the adoption process；the adoption of a policy；widespread adoption。','adaptation 是适应、改编；adoption 是接纳与采用。',('The family kept records of the adoption process.','这个家庭保存了收养过程的记录。'),('The new format gained widespread adoption among publishers.','这种新格式在出版商中得到了广泛采用。'),sources=['https://www.etymonline.com/word/adoption','https://www.oxfordlearnersdictionaries.com/definition/english/adoption']),
E('adopted','英 /əˈdɒptɪd/；美 /əˈdɑːptɪd/','被收养的；已采用的；选择定居认同的','一段接纳关系已经形成，或一种做法已经被选定。','adopt + -ed，词尾 /t/ 后的 -ed 读 /ɪd/，增加一个音节。',ADOPT+[['英语 adopt → adopted','接纳、采用 → 已被接纳、采用的']],'an adopted child 是被收养的孩子；an adopted country 是一个人后来选择生活、认同的国家；an adopted policy 是已经通过采用的政策。','an adopted child；an adopted country；a newly adopted policy。','adoptive parents 是收养方的父母；adopted child 是被收养方的孩子。',('She writes about growing up as an adopted child.','她写了自己作为被收养儿童长大的经历。'),('He returned to his adopted country after a year abroad.','在国外待了一年后，他回到自己选择定居的国家。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/adopted','https://www.merriam-webster.com/dictionary/adopted']),
E('adoptive','英 /əˈdɒptɪv/；美 /əˈdɑːptɪv/','收养关系中的；收养方的','描述因收养而形成的家庭关系，常落在父母、家庭这一侧。','由古法语 adoptif 或拉丁 adoptivus 借入，远接 adoptare；英语 adoptive 的早期记录甚至早于 adopt。',AD+[['拉丁语 adoptivus → 古法语 adoptif；亦可直接借拉丁语','属于收养关系的'],['英语 adoptive','收养的、因收养形成的']],'adoptive mother 是养母，adoptive family 是收养家庭。它不是说母亲本人被别人收养；具体关系方向需要结合名词判断。','adoptive parents；an adoptive family；an adoptive mother。','adopted 常表示被收养；adoptive 常修饰收养方或收养关系。',('Her adoptive parents encouraged her to explore her family history.','她的养父母鼓励她了解自己的家庭历史。'),('The workshop brings together members of adoptive families.','工作坊聚集了收养家庭的成员。'),sources=['https://www.etymonline.com/word/adoptive','https://www.oxfordlearnersdictionaries.com/definition/english/adoptive']),
E('adopter','英 /əˈdɒptə/；美 /əˈdɑːptər/','采用者；收养者','主动把新方法用起来的人，也可指承担收养关系的人。','adopt + -er，表示动作发起者；不同宾语决定是在讲技术采用还是收养。',ADOPT+[['英语 adopt + -er → adopter','采用、收养 → 采用者、收养者']],'early adopters 常指较早尝试新产品、技术或做法的一批人；在宠物或家庭收养材料里，adopter 指收养方。','an early adopter；technology adopters；a prospective adopter。','adopter 是采取行动的一方；adoptee 通常是被收养的人。',('Early adopters helped the company improve the software.','早期使用者帮助公司改进了软件。'),('The shelter asked each prospective adopter about their home environment.','收容所询问每位有意领养者的家庭环境。'),sources=['https://www.etymonline.com/word/adopter','https://www.oxfordlearnersdictionaries.com/definition/english/adopter']),
E('adoptable','英 /əˈdɒptəbəl/；美 /əˈdɑːptəbəl/','可采用的；可被收养或领养的','条件允许把它接纳进来，或它已经适合进入收养、领养程序。','adopt + -able；说具有可被采用或接纳的条件。',ADOPT+[['英语 adopt + -able → adoptable','采用、收养 → 可以被采用、收养的']],'动物救助材料里的 adoptable pets 指可供领养的宠物；方案语境里 adoptable proposal 指可采纳的提案。它不是 adored“深受喜爱的”。','adoptable animals；an adoptable proposal；readily adoptable methods。','adaptable 是能适应、能调整；adoptable 是能被采用或收养。',('The website lists adoptable cats from local shelters.','网站列出了当地收容所可供领养的猫。'),('The committee asked for a practical, adoptable proposal.','委员会要求提出切实可采纳的方案。'),sources=['https://www.merriam-webster.com/dictionary/adoptable','https://en.wiktionary.org/wiki/adoptable#English']),
E('adoptee','英 /əˌdɒpˈtiː/；美 /əˌdɑːpˈtiː/','被收养者','从关系的另一侧说：这个人是进入收养家庭的一方。','按 Merriam-Webster 等采用 adopt + -ee 的英语派生分析；-ee 常标记动作承受者，不能无条件当作法语 adoptée 整词借入。',ADOPT+[['英语 adopt + -ee → adoptee','收养 → 被收养的人']],'adoptee 可以是儿童，也可以是已经成年的被收养者。这个身份词只说明收养经历，并不限制年龄，也不替一个人概括全部家庭关系。','an adult adoptee；an adoptee support group；adoptees’ experiences。','adopter 是收养方；adoptee 是被收养方，重音也往词尾走。',('The interview focuses on the experiences of adult adoptees.','访谈聚焦成年被收养者的经历。'),('She joined a support group for adoptees.','她加入了一个被收养者互助小组。'),sources=['https://www.merriam-webster.com/dictionary/adoptee','https://www.etymonline.com/word/adoptee']),
E('optative','英 /ˈɒptətɪv/；美 /ˈɑːptətɪv/','祈愿的；祈愿语气〔语法〕','说的是“愿它如此”，而不是“事实就是如此”。','晚期拉丁 optativus 接 optatus“所希望的”，经法语 optatif 等进入英语；术语仿译希腊语的祈愿语法名称。',O+[['拉丁语 optatus → 晚期拉丁语 optativus','希望的 → 表示愿望的'],['法语 optatif → 英语 optative','语法中的祈愿形式、祈愿语气']],'古希腊语等有专门的 optative 动词形式，功能也不只限于愿望。英语 May you succeed! 是祈愿表达，但不宜据此说英语有与古希腊语完全一样的一套变位。','the optative mood；an optative form；an optative sentence。','indicative 常陈述事实；optative 与愿望、可能性等相关，具体功能依语言而定。',('“May you return safely” is an optative expression.','“愿你平安归来”是一种祈愿表达。'),('The grammar explains several uses of the Greek optative.','这本语法书解释了希腊语祈愿语气的几种用法。'),sources=['https://www.merriam-webster.com/dictionary/optative','https://en.wiktionary.org/wiki/optative#English']),
E('optation','英 /ɒpˈteɪʃən/；美 /ɑːpˈteɪʃən/','愿望；表达愿望〔罕用〕','把“希望发生什么”说出来，像向未来投出一句祝愿。','来自拉丁 optatio，接 optare“希望、选择”。不是从现代英语 opt 临时推出来的日常名词。',O+[['拉丁语 optatio → 英语 optation','愿望、祈愿 → 愿望的表达']],'常见于旧式修辞或辞书讨论；普通交流说 wish 更自然。它与 option 形近，但不表示菜单上的一个选项。','an expression of optation；optation in rhetoric；a solemn optation。','option 主要是可选方案或选择权；optation 在罕见用法里强调愿望。',('The critic reads the final line as an optation for peace.','评论者把最后一行理解为对和平的祈愿。'),('The old rhetoric manual gives an example of optation.','那本旧修辞手册举了一个表达愿望的例子。'),sources=['https://www.merriam-webster.com/dictionary/optate','https://en.wiktionary.org/wiki/optation#English']),
E('coopt','英 /kəʊˈɒpt/；美 /koʊˈɑːpt/','增选、吸收为成员；收编；挪用','先把别人拉进自己的队伍；后来也指把别人的力量、语言或理念拿来为自己服务。','拉丁 cooptare：com-“一起” + optare“选择”。coopt 是不带连字符的拼法，常见另一拼法为 co-opt。',CO,'委员会 coopt a member 是由现有成员增选新人；政治或商业评论里 coopt a movement 是吸纳并可能改变它的独立性。后一个用法常带批评。','coopt someone onto a committee；coopt a slogan；coopt an opposition group。','recruit 主要是招募；coopt 还可能含把外来力量吸收、改为己用的意味。',('The committee voted to coopt two additional members.','委员会投票决定增选两名成员。'),('The advertisement coopts the language of social change to sell shoes.','这则广告借用社会变革的语言来卖鞋。'),sources=['https://www.etymonline.com/word/co-opt','https://www.merriam-webster.com/dictionary/co-opt','https://en.wiktionary.org/wiki/coopt#English']),
E('cooption','英 /kəʊˈɒpʃən/；美 /koʊˈɑːpʃən/','增选；吸收、收编；挪用','把外部的人或力量纳入现有体系的这一步。','coopt + -ion；与较常排成 co-option 的形式相同，不是 co-“共同”加 option“选项”来表达共同选项。',CO+[['英语 coopt + -ion → cooption','吸收、收编 → 这种行为或安排']],'by cooption 是由现有成员增补，而非一般公众投票选出。评论运动或文化时，cooption 常指某种独立表达被大机构吸收改造。','appointment by cooption；political cooption；the cooption of a symbol。','cooperation 是合作；cooption 可能只是把对方吸收进来，并不保证平等合作。',('The vacant seat was filled by cooption.','空缺席位通过增选得到补充。'),('The essay questions the cooption of protest symbols by major brands.','文章质疑大品牌挪用抗议符号的做法。'),sources=['https://www.merriam-webster.com/dictionary/co-option','https://en.wiktionary.org/wiki/cooption#English']),
E('cooptation','英 /ˌkəʊɒpˈteɪʃən/；美 /ˌkoʊɑːpˈteɪʃən/','吸纳、收编；增选；挪为己用','把原本在外部的声音纳进制度中，也可能因此削弱它原来的独立方向。','早期名词来自拉丁 cooptatio，接 cooptare；英语记录早于 coopt。现代虽可对照 coopt + -ation，历史不能全部写成这种派生。',O+[['拉丁语 cooptare → cooptatio','选入团体 → 增选行为'],['英语 cooptation','增选；后来扩展为收编、挪用']],'与 cooption 意思高度重叠，cooptation 在政治、组织和文化评论中尤其常用。中性义是吸纳成员；带批评的用法关注吸纳后谁掌握议程。','political cooptation；resist cooptation；the cooptation of dissent。','integration 强调纳入整体；cooptation 在评论中常暗示原有反对声音被吸收、改变。',('The historian describes the cooptation of local leaders into the new administration.','历史学家描述了地方领袖被吸纳进新行政体系的过程。'),('The artists feared the commercial cooptation of their work.','艺术家们担心自己的作品被商业力量挪为己用。'),sources=['https://www.etymonline.com/word/cooptation','https://www.merriam-webster.com/dictionary/co-optation']),
]
THE_ROOT=dict(id='C1509',meaning='放置、设定；提出论点、插入、组合与容器',core='先想“把东西放到一个位置”：放出来供人讨论是主题、论点；放在一起是综合；插在话中间是插入语；安放东西的地方又能成为盒、库、店。',image='thesis 提出来；hypothesis 放在论证下面；synthesis 放在一起；parenthesis 插在旁边。thēkē 则从放置走向容器和储藏处。',intro='主线来自古希腊 tithenai，词典形式 tithemi“放、安置”。thesis、thema、thetos、theke 是相关古典词形，分别进入学术、日常和专业词汇。原表中的 treasure / thesaurus 保留为传统关联支线：它们的希腊源头 thesauros 更早来历未定。doom / deem 则是日耳曼继承词，最多谈更远的可能亲缘，绝非英语从希腊直接借入。',forms='thet-、thes-、themat-、thec- 分别见于形容词、thesis 词族、theme 词干及容器词族。这里的 the- 不等于英语冠词 the，也不是 theo-“神”。不同希腊复合词常已有独立名词与形容词，英语的短词不一定比长词早。',branches=[['主题、论点与设想','theme, themed, thematic, thematically, athematic, monothematic, thesis, theses, hypothesis, hypotheses, hypothesize, hypothetical, hypothetically'],['组合与合成','synthesis, syntheses, synthesize, synthesized, synthesizer, synthetic, synthetically, biosynthesis, biosynthetic, synthetase, polysynthetic, oligosynthetic, photosynthesis, photosynthetic'],['对照、插话与描述','antithesis, antithetic, antithetical, parenthesis, parenthetic, parenthetical, parenthetically, epithet'],['添加、连接与添音','prosthesis, prosthetic, prothesis, prothetic, epenthesis, epenthetic, enthesis, enthetic'],['规则、担保与强烈排斥','Themis, nomothetic, hypothec, hypothecate, hypothecation, anathema, anathematic'],['储藏处、壳与生物组织','boutique, bodega, bibliotheca, theca, epitheca, apothecium, pseudothecium, thecium'],['传统关联：宝库的更早源头未定','treasure, treasured, treasury, treasurer, thesaurus'],['日耳曼旁支：判断与厄运','doom, doomed, deem, doomsday, doomer, doomscroll, doomscrolling']],contrasts='synthetic 不自动等于劣质，hypothesis 不等于无根据乱猜。prosthesis 常是假体，prothesis 常是词首添音；enthesis 是附着部位，enthetic 是旧医学“外部传入”。treasure 和 doom 的历史不可为了一个整齐的“放置”故事而画成希腊直系。',practice='用一句话把 thesis、hypothesis、synthesis 的“放”分别讲出来。再解释 boutique 与 bodega 为什么是不同路线的亲属词，而 treasure 与 thesaurus 的更早来源仍应保留疑问。',words=list(ASSIGN['roots'][48]['family']),exclude={})
OPT_ROOT=dict(id='C0906',meaning='选择、希望；接纳与选入团体',core='面前有几种可能，选一项归自己用。option 是可选的路，opt 是作决定，adopt 是把选中的东西接纳进来。',image='option 把几扇门留着；opt 选一扇门走；adopt 把方法或关系接进生活；coopt 把原在外面的人或力量吸收到队伍里。',intro='拉丁 optare 表选择、希望，较远来源有不同解释。本族经过多次借入：option 经法语名词进入英语，比动词 opt 早；adoption、adoptive 在英语中也早于 adopt 的常见记录。cooptation 有早期拉丁名词路线，不能单凭长度推定它由现代 coopt 加后缀而来。',forms='opt- 表选择或希望。ad- + optare → adoptare 是为自己选择、接纳；com- + optare → cooptare 是选入共同团体。optional、optionally、optionality 是英语常规派生；optative 和 optation 保留“愿望”方向。',branches=[['选择、选项与选择余地','option, opt, optional, optionally, optionality, nonoptional'],['接纳、采用与收养关系','adopt, adoption, adopted, adoptive, adopter, adoptable, adoptee'],['希望的旧义与语法用法','optative, optation'],['选入团体、吸收与收编','coopt, cooption, cooptation']],contrasts='adopt 接纳，adapt 调整；adopter 是采取行动的一方，adoptee 是被收养者。optional 可不选，nonoptional 必须具备。cooption 不是 cooperation：吸纳进体系不等于平等合作。',practice='用 opt for、opt to、adopt 分别写一个选择场景。再说明 adopted child 与 adoptive parents 的关系方向，以及为什么 option 不能按英语 opt + -ion 的顺序讲借入史。',words=list(ASSIGN['roots'][49]['family']),exclude={})
roots=[THE_ROOT,OPT_ROOT]
